/**
 * Docs lag: the official HTM pages the app parses at runtime (runewords, gemwords, socketables, uniques, mythicals) are
 * generated by the mod author from the same tables the bundles come from. When a release changes a table but its pages
 * were not regenerated, the HTM-based pages show old data next to bundle pages with new data. Pure: the CLI passes the
 * changed paths of the clone between the old and the new revision.
 */
import { info, ok, finding, type Check } from './report.ts';

/** The excel tables the generated pages are built from, with the pages each one feeds (the app parses these pages). */
export const DOCS_PAGES_BY_TABLE: Readonly<Record<string, readonly string[]>> = {
  // runes.txt also holds the charm gemwords
  'runes.txt': ['runewords.htm', 'gemwords.htm'],
  'gems.txt': ['gems.htm'],
  'uniqueitems.txt': ['unique_weapons.htm', 'unique_armors.htm', 'unique_others.htm', 'unique_mythicals.htm'],
};

/** Every generated page the app parses (ascendancies.htm is hand-written and not generated from a table). */
export const APP_DOCS_PAGES: readonly string[] = [...new Set(Object.values(DOCS_PAGES_BY_TABLE).flat())];

const fileName = (path: string): string => path.slice(path.lastIndexOf('/') + 1);

/**
 * @param changedTables changed excel table paths (any directory; only the file name is used)
 * @param changedPages changed docs page paths of the default locale (`docs/<page>`; locale folders are ignored)
 */
export function docsLagCheck(changedTables: readonly string[], changedPages: readonly string[]): Check {
  const id = 'docs.lag';
  const title = 'Tables vs the generated docs pages';
  const tables = [...new Set(changedTables.map(fileName))].filter((table) => table in DOCS_PAGES_BY_TABLE).sort();
  const pages = new Set(changedPages.filter((path) => /^docs\/[^/]+$/.test(path)).map(fileName));

  if (tables.length === 0) return ok(id, title, 'No table behind the parsed docs pages changed.');

  const lines = tables.map((table) => {
    const fed = DOCS_PAGES_BY_TABLE[table] ?? [];
    const changed = fed.filter((page) => pages.has(page));
    return `${table} changed → ${changed.length === 0 ? 'none' : changed.join(', ')} of ${fed.join(', ')} changed`;
  });

  if (!APP_DOCS_PAGES.some((page) => pages.has(page))) {
    return finding(
      id,
      title,
      `${tables.join(', ')} changed but none of the docs pages the app parses did: the docs were probably not regenerated for this release`,
      'the runeword, gemword, socketable and unique pages parse these HTM pages at runtime, so players see the old data there while the bundle-based pages (sets, bases, cube, loot filter, stash) show the new data; ask the mod author to regenerate the docs',
      lines
    );
  }

  const lagging = tables.filter((table) => !(DOCS_PAGES_BY_TABLE[table] ?? []).some((page) => pages.has(page)));
  if (lagging.length > 0) {
    return info(
      id,
      title,
      `${lagging.join(', ')} changed but its pages did not (other pages were regenerated): the change may be in columns the pages do not show; check the table diff`,
      lines
    );
  }
  return ok(id, title, 'Every changed table has regenerated pages.', lines);
}
